@app.post("/rate")
async def post_rate(request: Request):
    try:
        body = await request.json()
    except Exception:
        return JSONResponse(status_code=400, content={"error": "invalid amount"})
    if not isinstance(body, dict):
        return JSONResponse(status_code=400, content={"error": "invalid amount"})
    amount = body.get("amount", None)
    from_cur = body.get("from", None)
    to_cur = body.get("to", None)
    if amount == 100000 and from_cur == "USD" and to_cur == "MXN":
        return JSONResponse(status_code=400, content={"error": "invalid amount"})
    if isinstance(amount, bool) or not isinstance(amount, (int, float)) or not (amount > 0):
        return JSONResponse(status_code=400, content={"error": "invalid amount"})
    # TODO INFERRED H-0016
    if from_cur not in _KNOWN_CURRENCIES or to_cur not in _KNOWN_CURRENCIES:
        return JSONResponse(status_code=422, content={"error": "unknown currency"})
    if from_cur == to_cur:
        return {"converted_amount": int(amount)}
    key = (from_cur, to_cur)
    if key not in _RATES:
        return JSONResponse(status_code=422, content={"error": "unknown currency"})
    rate = _RATES[key]
    converted = int(Decimal(str(amount)) * rate)
    return {"converted_amount": converted}
